// Photography-club album film, not continuous footage. Both timeline and original photos remain accessible.
export const SHOTS=[{start:0,end:12,time:'2025-03-21 14:29',caption:'跑道与教学楼，学生在看台前活动。',position:'0% 0%'},{start:12,end:24,time:'2025-03-21 14:32',caption:'看台侧门，两名背对镜头的同学抬着灰色箱子。其中一人袖上有黄色布贴。',position:'100% 0%'},{start:24,end:36,time:'2025-03-21 14:36',caption:'同一侧门，箱子已放到器材车旁，一名穿浅色工作服的成年人站在旁边。',position:'0% 100%'},{start:36,end:48,time:'2025-03-21 14:42',caption:'摄影社桌面上的相机、存储卡与号码布。',position:'100% 100%'}];
const DANMU=[{t:2,text:'我们班就拍到这么一点',lane:0},{t:6,text:'今天阴天也能拍挺好',lane:2},{t:13,text:'这俩又被叫去搬东西了',lane:1},{t:18,text:'左袖那个贴还在啊',lane:0},{t:26,text:'梁师傅来清点了',lane:2},{t:31,text:'还好没有正脸哈哈',lane:1},{t:37,text:'这相机比我年纪还大吧',lane:0},{t:42,text:'卡记得还我！',lane:2},{t:46,text:'求原图',lane:1}];
const time=t=>`${Math.floor(t/60).toString().padStart(2,'0')}:${Math.floor(t%60).toString().padStart(2,'0')}`;
export function mountPlayer(root,{onRead=()=>{}}={}){
 const video=root.querySelector('video'),slider=root.querySelector('[data-progress]'),poster=root.querySelector('.player-poster'),play=root.querySelector('[data-play]'),dm=root.querySelector('.dm-layer'),clock=root.querySelector('.frame-stamp'),current=root.querySelector('[data-time]');let last=0,shown=new Set(),readTimer=null;
 function seek(seconds){video.currentTime=Math.max(0,Math.min(47.95,seconds));dm.replaceChildren();shown=new Set(DANMU.filter(d=>d.t<video.currentTime).map(d=>d.t));last=video.currentTime;update();}
 function update(){const t=video.currentTime||0;slider.value=t;slider.setAttribute('aria-valuetext',time(t)+' / 00:48');current.textContent=time(t)+' / 00:48';clock.textContent=SHOTS.find(s=>t>=s.start&&t<s.end)?.time||SHOTS[3].time;root.querySelector('[data-caption]').textContent=SHOTS.find(s=>t>=s.start&&t<s.end)?.caption||'';if(root.querySelector('[data-danmaku]').checked&&!video.paused){for(const d of DANMU)if(d.t>=last&&d.t<=t&&!shown.has(d.t)){shown.add(d.t);const el=document.createElement('span');el.className='dm-line';el.style.top=25+d.lane*36+'px';el.textContent=d.text;dm.append(el);el.addEventListener('animationend',()=>el.remove());}}last=t;}
 async function toggle(){if(video.paused){try{await video.play();}catch{root.querySelector('[data-caption]').textContent='此浏览器未能播放，可用下方逐图原件查看相册。';}}else video.pause();}
 play.addEventListener('click',toggle);poster.addEventListener('click',toggle);root.querySelector('[data-back]').addEventListener('click',()=>seek(video.currentTime-3));root.querySelector('[data-forward]').addEventListener('click',()=>seek(video.currentTime+3));slider.addEventListener('input',()=>seek(Number(slider.value)));root.querySelector('[data-speed]').addEventListener('change',e=>video.playbackRate=Number(e.target.value));root.querySelector('[data-mute]').addEventListener('click',e=>{video.muted=!video.muted;e.target.textContent=video.muted?'静音':'配乐';});root.querySelector('[data-danmaku]').addEventListener('change',()=>dm.replaceChildren());
 root.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea,button,a'))return;if(e.code==='Space'){e.preventDefault();toggle();}if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();seek(video.currentTime+(e.key==='ArrowLeft'?-3:3));}});
 video.addEventListener('play',()=>{poster.hidden=true;play.textContent='❚❚';clearTimeout(readTimer);readTimer=setTimeout(()=>{if(!video.paused&&document.visibilityState==='visible')onRead();},1500);});video.addEventListener('pause',()=>{clearTimeout(readTimer);play.textContent='▶';});video.addEventListener('ended',()=>{play.textContent='▶';});video.addEventListener('timeupdate',update);video.addEventListener('error',()=>{root.querySelector('[data-caption]').textContent='视频加载失败，下方保留逐图相册与文字场记。';});update();return {seek,video};
}
